import { safeFetch } from "./utils/safeFetch";
import path from "path";
import {
  app,
  BrowserWindow,
  ipcMain,
  Menu,
  net,
  screen,
  session,
  Tray,
} from "electron";
import dotenv from "dotenv";

const assetsPath = app.isPackaged
  ? path.join(process.resourcesPath, "assets")
  : path.join(process.cwd(), "assets");

dotenv.config({ path: path.join(assetsPath, ".env") });

// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

ipcMain.handle("safe-fetch", async (e, url) => {
  return safeFetch(url, net.fetch.bind(net));
});

ipcMain.handle("get-app-version", () => app.getVersion());

ipcMain.handle("get-required-version", async () => {
  const token = process.env.DOPPLER_TOKEN;
  if (!token) throw new Error("DOPPLER_TOKEN is not set");

  const response = await net.fetch(
    "https://api.doppler.com/v3/configs/config/secret?project=gifly&config=prd&name=APP_VERSION",
    {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
      },
    }
  );

  if (!response.ok) {
    throw new Error(`Doppler API error: ${response.status}`);
  }

  const data = (await response.json()) as {
    name: string;
    value: { raw: string; computed: string; note: string };
  };
  return data.value.computed;
});

ipcMain.handle("copy-image-to-clipboard", async () => {
  try {
    const win = BrowserWindow.getFocusedWindow();

    if (!win) {
      console.error("Failed to copy image to clipboard: no focused window");
      return false;
    }

    win.webContents.sendInputEvent({
      type: "keyDown",
      keyCode: "C",
      modifiers: ["control"],
    });
    return true;
  } catch (error) {
    return false;
  }
});

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require("electron-squirrel-startup")) {
  app.quit();
}

const createWindow = (): void => {
  const { width, height } = screen.getPrimaryDisplay().workAreaSize;

  const windowWidth = 500;
  const windowHeight = 600;

  const mainWindow = new BrowserWindow({
    height: windowHeight,
    width: windowWidth,
    resizable: false,
    frame: false,
    skipTaskbar: true,
    alwaysOnTop: true,
    x: width - windowWidth,
    y: height - windowHeight,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      devTools: !app.isPackaged,
    },
  });

  const repositionWindow = () => {
    const { x, y, width, height } = screen.getPrimaryDisplay().workArea;
    mainWindow.setBounds({
      x: x + width - windowWidth,
      y: y + height - windowHeight,
      width: windowWidth,
      height: windowHeight,
    });
  };

  screen.on("display-metrics-changed", repositionWindow);
  screen.on("display-added", repositionWindow);
  screen.on("display-removed", repositionWindow);

  // and load the index.html of the app.
  mainWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY);

  // Content Security Policy
  session.defaultSession.webRequest.onHeadersReceived((details, callback) => {
    const csp =
      "default-src 'self' 'unsafe-inline' 'unsafe-eval' data:; img-src *";

    callback({
      responseHeaders: {
        ...details.responseHeaders,
        "Content-Security-Policy": [csp],
      },
    });
  });

  const tray = new Tray(path.join(assetsPath, "icon.png"));
  const contextMenu = Menu.buildFromTemplate([
    { label: "Show App", click: () => mainWindow.show() },
    {
      label: "Restart",
      click: () => {
        app.relaunch();
        app.exit();
      },
    },
    { label: "Quit", click: () => app.quit() },
  ]);

  tray.setToolTip("Gifly");
  tray.setContextMenu(contextMenu);

  // race condition fix (scuffed)

  let ignoreBlur = false;
  let ignoreShow = false;

  tray.on("click", () => {
    if (mainWindow.isVisible()) {
      mainWindow.hide();
    } else {
      if (!ignoreShow) {
        ignoreBlur = true;
        mainWindow.show();

        setTimeout(() => {
          ignoreBlur = false;
        }, 500);
      }
    }
  });

  mainWindow.on("blur", () => {
    if (!ignoreBlur) {
      ignoreShow = true;
      mainWindow.hide();

      setTimeout(() => {
        ignoreShow = false;
      }, 500);
    }
  });

  mainWindow.minimize();
};

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
app.on("ready", createWindow);

// Quit when all windows are closed, except on macOS. There, it's common
// for applications and their menu bar to stay active until the user quits
// explicitly with Cmd + Q.
app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});

app.on("activate", () => {
  // On OS X it's common to re-create a window in the app when the
  // dock icon is clicked and there are no other windows open.
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});

